from llm_saea import Plan, benchmark, optimize

PLAN = Plan.from_dict({'surrogate': 'auto', 'operator': 'current_to_best', 'mutation': 0.5, 'crossover': 0.7, 'exploration': 0.6, 'local_fraction': 0.45, 'radius': 0.2, 'population': 30, 'generations': 5, 'reason': "Stagnation with zero recent improvement and a fairly small evaluation budget suggests shifting toward exploration rather than pure local refinement. Raising exploration and local radius lets the surrogate's novelty term drive sampling away from a stalled region, while auto keeps the surrogate choice adaptive between RBF and quadratic as data accumulates. current_to_best balances convergence with diversity; moderate mutation/crossover keep candidate generation stable given only 5 dims. Population and generations are trimmed to conserve the fixed budget for more sequential model updates."})

def solve(problem, budget=100, seed=0):
    return optimize(problem, budget=budget, seed=seed, method='saea', plan=PLAN)

if __name__ == '__main__':
    result = solve(benchmark('sphere', 5))
    print({'best_y': result.best_y, 'best_x': result.best_x.tolist()})
